// FIX16: brújula GEOGRÁFICA en el mapa; independiente del pronóstico modal.
// Leaflet no rota el mapa en esta versión web, por lo que el norte siempre queda arriba.
state.focusSiteId=null;
state.centerWind=null;
state.centerWindTimer=null;
function centerForecastSite(){
  const focus=state.sites.find(s=>s.id===state.focusSiteId);
  if(focus)return focus;
  if(!state.map)return null;
  const c=state.map.getCenter();
  return [...state.sites].sort((a,b)=>(a.lat-c.lat)**2+(a.lon-c.lng)**2-( (b.lat-c.lat)**2+(b.lon-c.lng)**2 ))[0]||null;
}
function mapCompassSvg(site,h){
 const dir=Number.isFinite(state.centerWind?.dir)?state.centerWind.dir:h?.dir;
 const valid=site?.windFromDirections||[];
 const arc=(deg,r,width,color,opacity)=>{const a=(deg-width/2)*Math.PI/180,b=(deg+width/2)*Math.PI/180;const p=x=>`${(70+r*Math.sin(x)).toFixed(2)} ${(70-r*Math.cos(x)).toFixed(2)}`;return `<path d="M ${p(a)} A ${r} ${r} 0 0 1 ${p(b)}" fill="none" stroke="${color}" stroke-width="${opacity===.9?5:10}" stroke-linecap="round" opacity="${opacity}"/>`};
 const bands=valid.map(d=>arc(d,58,60,'#36e398',.23)+arc(d,58,30,'#36e398',.9)).join('');
 const labels=sectors.map((label,i)=>{const a=i*22.5*Math.PI/180;const r=i%4===0?43:49;return `<text x="${70+r*Math.sin(a)}" y="${74-r*Math.cos(a)}" fill="${i===0?'#ff792d':'#d6e8fa'}" font-size="${i%4===0?10:6.8}" font-weight="800" text-anchor="middle">${label}</text>`}).join('');
 return `<svg viewBox="0 0 140 140" role="img" aria-label="Brújula geográfica con norte fijo"><circle cx="70" cy="70" r="67" fill="#07182f" stroke="#31516c" stroke-width="2"/>${bands}${labels}${Number.isFinite(dir)?`<g transform="rotate(${dir} 70 70)"><path d="M70 8L63 31L70 26L77 31Z" fill="#ff7b27"/><path d="M70 132L63 109L70 114L77 109Z" fill="#57c3ff"/><path d="M70 30V110" stroke="#ff8935" stroke-width="2"/></g>`:''}<circle cx="70" cy="70" r="10" fill="#102c4c" stroke="#3b6686"/><text x="70" y="73" text-anchor="middle" fill="#fff" font-size="8" font-weight="900">${Number.isFinite(dir)?windLabel(dir):'N↑'}</text></svg>`;
}
function updateMapCompass(){
 const box=$('mapCompass');if(!box)return;
 const site=centerForecastSite(),h=site?hourFor(site):null,w=state.centerWind;
 const dir=Number.isFinite(w?.dir)?w.dir:h?.dir;
 box.innerHTML=`${mapCompassSvg(site,h)}<div class="map-compass-caption"><strong>VIENTO MAPA · NORTE FIJO</strong><span>${Number.isFinite(dir)?`${windLabel(dir)} ${Math.round(dir)}° → ${windLabel((dir+180)%360)}`:'Dirección —'}</span><span>${Number.isFinite(w?.wind)?Math.round(w.wind):fmt(h?.wind)} km/h · ráf. ${Number.isFinite(w?.gust)?Math.round(w.gust):fmt(h?.gust)} km/h</span><small>${site?safe(site.name)+' · '+site.windFromDirections.map(windLabel).join(' · '):'Seleccioná un despegue'}</small></div>`;
}
function scheduleCenterWind(){
 clearTimeout(state.centerWindTimer);
 state.centerWindTimer=setTimeout(async()=>{
  if(!state.map)return;
  const c=state.map.getCenter(),key=`${c.lat.toFixed(2)},${c.lng.toFixed(2)}`;
  const request=state.centerWindRequest=(state.centerWindRequest||0)+1;
  let cache=state.centerCache.get(key);
  if(!cache||Date.now()-cache.at>20*60*1000){
   const results=await fetchModelForecast(c.lat,c.lng,3,'wind_speed_10m,wind_gusts_10m,wind_direction_10m');
   const rows=mergeModels(results);cache={at:Date.now(),rows};if(rows.length){state.centerCache.set(key,cache);if(state.centerCache.size>20)state.centerCache.delete(state.centerCache.keys().next().value)}
  }
  if(request!==state.centerWindRequest)return;
  const target=Date.now()+state.selectedTime*3600000;
  const h=cache?.rows.find(h=>h.ts>=target-45*60*1000)||cache?.rows[0];
  state.centerWind=h?{wind:h.wind,gust:h.gust,dir:h.dir,models:h.models}:null;
  renderWindLayer();updateMapCompass();
 },650);
}

// V1.17 · La hora es individual de cada navegador: no se sincroniza con otros visitantes.
function updateTimeLabel(){const d=new Date(Date.now()+state.selectedTime*3600000);$('timeLabel').textContent=state.selectedTime===0?'Ahora':d.toLocaleString('es-AR',{weekday:'short',day:'2-digit',hour:'2-digit',minute:'2-digit'});}
function showQuickSite(id){const s=state.sites.find(x=>x.id===id);if(!s)return;const h=hourFor(s),a=assess(s,h),next=(state.weather.get(id)||[]).filter(x=>x.ts>=Date.now());const windowHours=next.filter(x=>assess(s,x).kind==='good').slice(0,3);$('quickContent').innerHTML=`<div class="eyebrow">DESPEGUE · CONSULTA RÁPIDA</div><h2>${safe(s.name)}</h2><div class="status ${a.kind}">${safe(a.label)}</div><p>${safe(a.reason)}</p><div class="quick-metrics"><div><small>VIENTO</small><b>${fmt(h?.wind)} km/h</b></div><div><small>RÁFAGA</small><b>${fmt(h?.gust)} km/h</b></div><div><small>DIRECCIÓN</small><b>${windLabel(h?.dir)} ${fmt(h?.dir)}°</b></div></div><p class="source-note">Próximas horas favorables según el pronóstico combinado: ${windowHours.length?windowHours.map(x=>safe(x.local.slice(5,16).replace('T',' '))).join(' · '):'No identificadas'}</p><div class="dialog-actions"><button class="orange-btn" data-action="detail" data-id="${safe(id)}">Ver pronóstico completo</button><button class="ghost" data-action="favorite" data-id="${safe(id)}">★ Favorito</button>${state.token?`<button class="ghost" data-action="edit" data-id="${safe(id)}">Editar</button><button class="ghost danger-btn" data-action="delete" data-id="${safe(id)}">Eliminar</button>`:''}</div>`;state.quickSiteId=id;$('quickDialog').showModal();}
function forecastInsights(s,hs){
 const good=hs.filter(h=>assess(s,h).kind==='good'), intervals=[];let first=null,last=null;
 for(const h of hs){if(assess(s,h).kind==='good'){if(!first)first=h;last=h}else if(first){intervals.push([first,last]);first=null;last=null}}if(first)intervals.push([first,last]);
 const windows=intervals.map(([a,b])=>a.local.slice(11,16)+'–'+String(Math.min(24,Number(b.local.slice(11,13))+1)).padStart(2,'0')+':00');
 const valid=hs.filter(h=>Number.isFinite(h.wind)&&Number.isFinite(h.gust));
 const limit=Number(s.maxGust??35), top=Math.max(20,Math.ceil(Math.max(limit,...valid.map(h=>Math.max(h.wind,h.gust)))/10)*10);
 const W=780,H=238,left=45,right=16,upper=15,bottom=35,plotW=W-left-right,plotH=H-upper-bottom;
 const x=i=>left+(i/Math.max(1,valid.length-1))*plotW;
 const y=n=>upper+(1-n/top)*plotH;
 const line=key=>valid.map((h,i)=>`${x(i).toFixed(1)},${y(h[key]).toFixed(1)}`).join(' ');
 const grid=[0,.25,.5,.75,1].map(f=>{const v=top*f, yy=y(v);return `<line x1="${left}" x2="${W-right}" y1="${yy}" y2="${yy}" stroke="#355777" stroke-width="1" opacity=".7"/><text x="${left-9}" y="${yy+4}" fill="#b8d0e5" font-size="12" text-anchor="end">${Math.round(v)}</text>`}).join('');
 const ticks=valid.map((h,i)=>i%3===0||i===valid.length-1?`<line x1="${x(i)}" x2="${x(i)}" y1="${upper}" y2="${H-bottom}" stroke="#2c4c69" opacity=".35"/><text x="${x(i)}" y="${H-12}" fill="#c6d8e9" font-size="12" text-anchor="middle">${safe(h.local.slice(11,16))}</text>`:'').join('');
 const maxWind=Math.max(0,...valid.map(h=>h.wind)),maxGust=Math.max(0,...valid.map(h=>h.gust));
 const chart=`<div class="wind-graph enhanced-graph"><div class="wind-chart-title"><strong>VIENTO Y RÁFAGAS · ${safe(hs[0]?.local.slice(8,10)+'/'+hs[0]?.local.slice(5,7))}</strong><span>km/h · horas locales</span></div><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Gráfico horario de viento y ráfagas en kilómetros por hora, con eje horario y límite de ráfagas">${grid}${ticks}<line x1="${left}" x2="${W-right}" y1="${y(limit)}" y2="${y(limit)}" stroke="#ff6878" stroke-width="2" stroke-dasharray="7 6"/><polyline points="${line('gust')}" fill="none" stroke="#ff9b42" stroke-width="3.5" stroke-linejoin="round" stroke-linecap="round"/><polyline points="${line('wind')}" fill="none" stroke="#4dcaff" stroke-width="3.5" stroke-linejoin="round" stroke-linecap="round"/></svg><div class="graph-legend"><span>🔵 Viento 10 m</span><span>🟠 Ráfagas</span><span class="limit-legend">- - Límite ${fmt(limit)} km/h</span></div></div>`;
 return `<section class="forecast-insights"><div class="insight-top"><div><strong>EVOLUCIÓN DEL VIENTO</strong><p>${windows.length?'Ventanas favorables: '+safe(windows.join(' · ')):'No se detectaron ventanas favorables'}</p><small>${good.length}/${hs.length} horas favorables según los criterios del despegue. No equivale a autorización de vuelo.</small></div></div><div class="wind-summary-cards"><div><small>VIENTO MÁXIMO</small><strong>${fmt(maxWind)} km/h</strong></div><div><small>RÁFAGA MÁXIMA</small><strong>${fmt(maxGust)} km/h</strong></div><div><small>LÍMITE CONFIGURADO</small><strong>${fmt(limit)} km/h</strong></div></div>${chart}<div class="model-section"><div class="model-section-heading"><div><strong>COMPARACIÓN DE MODELOS</strong><small>ECMWF IFS · ICON · GFS · GEM</small></div><button type="button" class="ghost" data-action="models" data-id="${safe(s.id)}" data-day="${safe(hs[0]?.local.slice(0,10)||'')}">Actualizar comparación</button></div><div id="modelComparison" class="model-comparison" aria-live="polite"><p>Abriendo la comparación de modelos…</p></div></div></section>`;
}
// Open-Meteo permite solicitar modelos por separado. No se inventa consenso ni confianza.
async function loadModelComparison(id,day,force=false){
 const site=state.sites.find(x=>x.id===id),el=$('modelComparison');if(!site||!el||!day)return;
 const key=id+'|'+day;el.dataset.requestKey=key;el.innerHTML='<div class="model-loading">Cargando los modelos que forman la tabla…</div>';
 let results=state.modelHourly.get(id);
 if(force||!results){results=await fetchModelForecast(site.lat,site.lon);state.modelHourly.set(id,results);const merged=mergeModels(results);if(merged.length){state.weather.set(id,merged);renderCards();renderMarkers()}}
 if(!el.isConnected||el.dataset.requestKey!==key)return;
 const daily=results.map(r=>r.rows?{name:r.name,rows:r.rows.filter(h=>h.local.startsWith(day))}:{name:r.name,error:r.error});
 const ok=daily.filter(r=>r.rows?.length);const combined=(state.weather.get(id)||[]).filter(h=>h.local.startsWith(day));
 const summary=ok.length?`${ok.length}/4 modelos disponibles para este día. La tabla y el semáforo utilizan los promedios horarios de estos mismos modelos.`:'No hay modelos disponibles para este día.';
 const max=(arr,key)=>arr.length?Math.max(...arr.map(h=>Number.isFinite(h[key])?h[key]:0)):null;
 const rows=daily.map(r=>r.rows?.length?`<tr><th>${safe(r.name)}</th><td>${fmt(max(r.rows,'wind'))} km/h</td><td>${fmt(max(r.rows,'gust'))} km/h</td><td>${r.rows.filter(h=>assess(site,h).kind==='good').length} h</td></tr>`:`<tr><th>${safe(r.name)}</th><td colspan="3">${safe(r.error||'Sin datos para este día')}</td></tr>`).join('');
 const combinedRow=combined.length?`<tr><th>Combinado · tabla</th><td>${fmt(max(combined,'wind'))} km/h</td><td>${fmt(max(combined,'gust'))} km/h</td><td>${combined.filter(h=>assess(site,h).kind==='good').length} h</td></tr>`:'';
 const times=combined.filter((_,i)=>i%3===0);const gustRows=[...daily.filter(r=>r.rows?.length),{name:'Combinado · tabla',rows:combined}].map(r=>`<tr><th>${safe(r.name)}</th>${times.map(h=>`<td>${fmt(r.rows.find(z=>z.ts===h.ts)?.gust)}</td>`).join('')}</tr>`).join('');
 el.innerHTML=`<p class="model-summary">${safe(summary)} El acuerdo entre modelos no es una probabilidad de seguridad.</p><div class="model-table-wrap"><table><thead><tr><th>Modelo</th><th>Viento máx.</th><th>Ráfaga máx.</th><th>Horas favorables</th></tr></thead><tbody>${combinedRow}${rows}</tbody></table></div>${times.length?`<h4>Ráfagas por hora · km/h</h4><div class="model-table-wrap"><table><thead><tr><th>Modelo</th>${times.map(h=>`<th>${safe(h.local.slice(11,16))}</th>`).join('')}</tr></thead><tbody>${gustRows}</tbody></table></div>`:''}<small>Fuente: Open-Meteo, modelos ECMWF IFS, ICON, GFS y GEM. Cada variable se promedia con los modelos que la proporcionan. Verificá las condiciones reales en el lugar.</small>`;
}
function updateEditorPreview(){const el=$('editorPreview');if(!el)return;const dirs=state.selectedDirections.map(windLabel).join(' · ')||'Sin orientación';el.innerHTML=`<strong>Vista previa del despegue</strong><span>${safe($('siteName').value.trim()||'Nuevo despegue')}</span><small>Orientaciones: ${safe(dirs)} · viento máx. ${safe($('siteMaxWind').value)} km/h · ráfagas máx. ${safe($('siteMaxGust').value)} km/h</small>`}
// Flujo animado original Apex Social: partículas de viento a 10 m, dirección uniforme.
// Es una visualización orientativa del pronóstico en el centro del mapa, NO un campo espacial.
const ApexWindFlow=L.Layer.extend({
 onAdd(map){this._map=map;this._canvas=L.DomUtil.create('canvas','apex-wind-flow');this._canvas.setAttribute('aria-hidden','true');this._canvas.style.pointerEvents='none';map.getPanes().overlayPane.appendChild(this._canvas);this._ctx=this._canvas.getContext('2d',{alpha:true});this._seed=0;this._particles=[];this._last=0;this._onResize=()=>this._resize();map.on('moveend zoomend resize',this._onResize);this._resize();this._tick=this._tick.bind(this);this._raf=requestAnimationFrame(this._tick)},
 onRemove(map){cancelAnimationFrame(this._raf);map.off('moveend zoomend resize',this._onResize);this._canvas.remove();this._ctx=null},
 setWind(deg,speed){if(this._dir===deg&&this._speed===speed)return;this._dir=deg;this._speed=speed;this._last=0},
 _resize(){if(!this._map||!this._canvas)return;const size=this._map.getSize(),pos=this._map.containerPointToLayerPoint([0,0]);L.DomUtil.setPosition(this._canvas,pos);const dpr=Math.min(window.devicePixelRatio||1,2);this._w=size.x;this._h=size.y;this._canvas.width=Math.round(size.x*dpr);this._canvas.height=Math.round(size.y*dpr);this._canvas.style.width=size.x+'px';this._canvas.style.height=size.y+'px';this._ctx.setTransform(dpr,0,0,dpr,0,0);this._particles=[]},
 _tick(now){this._raf=requestAnimationFrame(this._tick);if(!this._ctx||document.hidden||!this._w||!this._h)return;if(now-this._last<33)return;const dt=Math.min((now-this._last||33)/33,2);this._last=now;const ctx=this._ctx,w=this._w,h=this._h;ctx.clearRect(0,0,w,h);if(!Number.isFinite(this._dir))return;const rad=(this._dir+180)*Math.PI/180;const vx=Math.sin(rad),vy=-Math.cos(rad);const count=Math.min(145,Math.max(30,Math.floor(w*h/5200)));while(this._particles.length<count)this._particles.push({x:Math.random()*w,y:Math.random()*h,life:Math.random()*130,age:Math.random()*90,len:15+Math.random()*23,speed:.65+Math.random()*.75});const pace=Math.min(2.4,Math.max(.45,(this._speed||8)/18));ctx.lineWidth=2.15;ctx.lineCap='round';for(const p of this._particles){const travel=pace*p.speed*dt*1.5;p.x+=vx*travel;p.y+=vy*travel;p.age+=dt;p.life-=dt;const opacity=Math.min(1,p.age/20,p.life/25);if(p.x< -40||p.x>w+40||p.y< -40||p.y>h+40||p.life<=0){p.x=Math.random()*w;p.y=Math.random()*h;p.life=55+Math.random()*105;p.age=0;continue}const g=ctx.createLinearGradient(p.x-vx*p.len,p.y-vy*p.len,p.x,p.y);g.addColorStop(0,'rgba(92,205,245,0)');g.addColorStop(1,`rgba(132,224,255,${(.68*opacity).toFixed(3)})`);ctx.strokeStyle=g;ctx.beginPath();ctx.moveTo(p.x-vx*p.len,p.y-vy*p.len);ctx.lineTo(p.x,p.y);ctx.stroke()}}
});
function renderWindLayer(){if(!state.map)return;if(!state.windEnabled){if(state.windLayer){state.map.removeLayer(state.windLayer);state.windLayer=null}$('windInfo').textContent='';return}const h=state.centerWind,dir=Number.isFinite(h?.dir)?h.dir:null;if(dir===null){$('windInfo').textContent='Esperando datos de viento en el centro del mapa';return}if(!state.windLayer){state.windLayer=new ApexWindFlow();state.windLayer.addTo(state.map)}state.windLayer.setWind(dir,Number.isFinite(h.wind)?h.wind:0);$('windInfo').textContent=`Flujo animado · viento multimodelo a 10 m en el centro del mapa: ${fmt(h.wind)} km/h · desde ${windLabel(dir)} · representación uniforme orientativa, no viento real en cada punto.`}
// V1.25 · buscador de lugares y despegues. Photon permite sugerencias de POI,
// Nominatim se usa solo al solicitar una búsqueda explícita (nunca autocomplete).
let placeRequest=0,placeTimer=null,placeAbort=null,placeItems=[];
function placeHide(){const el=$('placeResults');el.hidden=true;$('search').setAttribute('aria-expanded','false')}
function placeCategory(p){const x=p||{};const t=String(x.osm_value||x.type||'').toLowerCase();if(['dam','weir'].includes(t))return ['Represa','🏞️'];if(t.includes('national_park')||t.includes('protected_area'))return ['Parque nacional','🌲'];if(['lake','reservoir','water'].includes(t))return ['Lago / embalse','🌊'];if(['peak','mountain','volcano'].includes(t))return ['Cerro / montaña','⛰️'];if(['city','town','village','hamlet','municipality'].includes(t))return ['Ciudad / localidad','📍'];if(['aerodrome','airport'].includes(t))return ['Aeropuerto','✈️'];if(['street','residential','road','house'].includes(t))return ['Dirección','🛣️'];return ['Lugar','📌']}
function placeName(p){return [p.name,p.city&&p.city!==p.name?p.city:null,p.state,p.country].filter(Boolean).join(', ')}
function placeLocal(q){const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es');const needle=norm(q);return state.sites.filter(s=>norm(s.name).includes(needle)).slice(0,7)}
function placeDraw(q,places=[],status=''){const box=$('placeResults');if(!q.trim()){placeHide();return}const local=placeLocal(q);placeItems=places;const siteHtml=local.map(s=>`<button type="button" class="place-option" data-place-site="${safe(s.id)}"><span>🪂</span><span><strong>${safe(s.name)}</strong><small>Despegue registrado · Ir al mapa</small></span></button>`).join('');const placeHtml=places.map((p,i)=>{const [kind,emoji]=placeCategory(p);return `<button type="button" class="place-option" data-place-index="${i}"><span>${emoji}</span><span><strong>${safe(p.name||'Lugar sin nombre')}</strong><small>${safe(kind)} · ${safe([p.city&&p.city!==p.name?p.city:null,p.state,p.country].filter(Boolean).join(', '))}</small></span></button>`}).join('');box.innerHTML=siteHtml+placeHtml+(status?`<div class="place-loading">${safe(status)}</div>`:'');box.hidden=false;$('search').setAttribute('aria-expanded','true')}
function placeFly(lat,lon,zoom){if(!Number.isFinite(lat)||!Number.isFinite(lon))return;state.searchCityMode=false;placeHide();if(state.view!=='map'){document.querySelector('.nav[data-view="map"]')?.click()}const map=state.map;if(!map)return;map.stop();map.flyTo([lat,lon],Math.max(12,Math.min(17,zoom)),{animate:true,duration:2.1,easeLinearity:0.22,noMoveStart:false})}
function placeZoom(p){const kind=String(p.osm_value||p.type||'').toLowerCase();if(['national_park','protected_area','forest'].includes(kind))return 11;if(['lake','reservoir','water'].includes(kind))return 12;if(['city','town','municipality'].includes(kind))return 14;if(['village','hamlet'].includes(kind))return 15;return 16}
async function placeSuggest(){const q=$('search').value.trim();if(q.length<3){placeDraw(q);return}const request=++placeRequest;if(placeAbort)placeAbort.abort();placeAbort=new AbortController();placeDraw(q,[],'Buscando lugares…');try{const url=new URL('https://photon.komoot.io/api/');url.searchParams.set('q',q);url.searchParams.set('limit','8');url.searchParams.set('lang','es');const c=state.map?.getCenter();if(c){url.searchParams.set('lat',String(c.lat));url.searchParams.set('lon',String(c.lng))}const response=await fetch(url,{signal:placeAbort.signal});if(!response.ok)throw Error('Servicio no disponible');const json=await response.json();if(request!==placeRequest||q!==$('search').value.trim())return;const places=(json.features||[]).filter(f=>f.geometry?.coordinates?.length>=2).map(f=>({...f.properties,lon:Number(f.geometry.coordinates[0]),lat:Number(f.geometry.coordinates[1])})).filter(p=>Number.isFinite(p.lat)&&Number.isFinite(p.lon));placeDraw(q,places,places.length?'':'Sin lugares coincidentes. Probá Buscar para una búsqueda más amplia.')}catch(e){if(request===placeRequest&&e.name!=='AbortError')placeDraw(q,[],'No se pudieron cargar sugerencias. Probá Buscar.')}}
async function placeFindCity(){const q=$('search').value.trim();if(q.length<2)return;const request=++placeRequest;if(placeAbort)placeAbort.abort();placeAbort=new AbortController();clearTimeout(placeTimer);placeDraw(q,[],'Buscando lugares…');try{const url=new URL('https://nominatim.openstreetmap.org/search');url.searchParams.set('q',q);url.searchParams.set('format','jsonv2');url.searchParams.set('addressdetails','1');url.searchParams.set('limit','8');url.searchParams.set('accept-language','es');const response=await fetch(url,{signal:placeAbort.signal});if(!response.ok)throw Error('Servicio no disponible');const json=await response.json();if(request!==placeRequest)return;const places=json.map(x=>({name:x.name||x.display_name?.split(',')[0],city:x.address?.city||x.address?.town||x.address?.village,state:x.address?.state,country:x.address?.country,osm_value:x.type,lat:Number(x.lat),lon:Number(x.lon),boundingbox:x.boundingbox})).filter(p=>Number.isFinite(p.lat)&&Number.isFinite(p.lon));placeDraw(q,places,places.length?'':'No encontramos ese lugar. Probá con otro nombre.')}catch(e){if(request===placeRequest&&e.name!=='AbortError')placeDraw(q,[],'No se pudo consultar el buscador. Revisá la conexión.')}}
function initPlaceSearch(){const inp=$('search');inp.placeholder='Ciudad, parque, represa, lago o despegue…';inp.addEventListener('input',()=>{placeRequest++;placeAbort?.abort();clearTimeout(placeTimer);const q=inp.value.trim();placeDraw(q);if(q.length>=3)placeTimer=setTimeout(placeSuggest,750)});inp.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();const first=$('placeResults').querySelector('.place-option');if(first&&!$('placeResults').hidden){first.click()}else placeFindCity()}if(e.key==='Escape')placeHide()});$('placeSearchBtn').addEventListener('click',placeFindCity);$('placeResults').addEventListener('click',e=>{const btn=e.target.closest('button');if(!btn)return;if(btn.dataset.placeSite){const s=state.sites.find(x=>x.id===btn.dataset.placeSite);if(s){inp.value=s.name;placeFly(Number(s.lat),Number(s.lon),16);state.focusSiteId=s.id;updateMapCompass()}return}if(btn.dataset.placeIndex!==undefined){const p=placeItems[Number(btn.dataset.placeIndex)];if(p){inp.value=placeName(p);placeFly(p.lat,p.lon,placeZoom(p))}}});document.addEventListener('click',e=>{if(!e.target.closest('.apex-place-search'))placeHide()})}

function init(){document.body.classList.add('map-mode');initMap();loadSites();scheduleCenterWind();initPlaceSearch();$('filter').addEventListener('change',render);$('refreshBtn').addEventListener('click',()=>loadWeather());$('timeSlider').addEventListener('input',e=>{state.selectedTime=Number(e.target.value);updateTimeLabel();render();scheduleCenterWind();});$('timeNow').addEventListener('click',()=>{$('timeSlider').value='0';state.selectedTime=0;updateTimeLabel();render();scheduleCenterWind()});$('windToggle').classList.add('active');$('windToggle').setAttribute('aria-pressed','true');$('windToggle').addEventListener('click',()=>{state.windEnabled=!state.windEnabled;$('windToggle').classList.toggle('active',state.windEnabled);$('windToggle').setAttribute('aria-pressed',String(state.windEnabled));renderWindLayer()});updateTimeLabel();$('layerBtn').addEventListener('click',()=>{state.map.removeLayer(state.satellite?state.sat:state.osm);state.satellite=!state.satellite;(state.satellite?state.sat:state.osm).addTo(state.map);$('layerBtn').textContent=state.satellite?'Vista: Satélite':'Vista: Calles';$('layerBtn').title=state.satellite?'Estás viendo Satélite. Clic para cambiar a Calles':'Estás viendo Calles. Clic para cambiar a Satélite'});document.querySelectorAll('.nav[data-view]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.nav[data-view]').forEach(b=>b.classList.toggle('active',b===btn));state.view=btn.dataset.view;document.body.classList.toggle('map-mode',state.view==='map');$('pageTitle').textContent=state.view==='favorites'?'Mis favoritos':state.view==='forecast'?'Pronóstico de vuelo':'Mapa de despegues';$('pageSub').textContent=state.view==='forecast'?'Seleccioná un despegue para consultar las próximas 24 horas':'Explorá lugares, orientaciones y condiciones previstas';render();requestAnimationFrame(()=>state.map?.invalidateSize({pan:false}))}));state.map.on('click',e=>{if(state.pickLocation){setDraftLocation(e.latlng.lat,e.latlng.lng);finishPick()}});$('pickMapBtn').addEventListener('click',startPick);$('pickDoneBtn').addEventListener('click',finishPick);$('siteLat').addEventListener('change',updateDraftMarker);$('siteLon').addEventListener('change',updateDraftMarker);['siteMaxGust','siteMaxWind','siteTolerance','siteName'].forEach(id=>$(id).addEventListener('input',updateEditorPreview));$('editDialog').addEventListener('close',()=>{if(!state.pickLocation)clearDraft();state.map?.closePopup()});$('adminBtn').addEventListener('click',()=>state.token?(state.token='',clearDraft(),render(),toast('Administración cerrada')):openAdmin());$('addBtn').addEventListener('click',()=>openEdit(null));$('manageBtn').addEventListener('click',openManage);$('manageAdd').addEventListener('click',()=>{$('manageDialog').close();openEdit(null)});$('manageSearch').addEventListener('input',renderManage);$('manageList').addEventListener('click',async e=>{const b=e.target.closest('[data-manage]');if(!b)return;const id=b.dataset.id;if(b.dataset.manage==='edit'){$('manageDialog').close();openEdit(id)}else await deleteSite(id)});$('loginBtn').addEventListener('click',adminLogin);$('editForm').addEventListener('submit',saveEdit);$('sectors').addEventListener('click',e=>{const btn=e.target.closest('[data-deg]');if(!btn)return;const deg=Number(btn.dataset.deg);state.selectedDirections=state.selectedDirections.includes(deg)?state.selectedDirections.filter(x=>x!==deg):[...state.selectedDirections,deg];renderSectors();updateEditorPreview()});document.addEventListener('click',e=>{const close=e.target.closest('[data-close]');if(close){$(close.dataset.close).close();return}const tabBtn=e.target.closest('[data-forecast-tab]');if(tabBtn){state.forecastTab=tabBtn.dataset.forecastTab;applyForecastTab();if(state.forecastTab==='evolution'&&state.focusSiteId&&state.forecastDay)loadModelComparison(state.focusSiteId,state.forecastDay);return}const btn=e.target.closest('[data-action]');if(!btn)return;const {action,id}=btn.dataset;if(action==='favorite'){state.favorites.has(id)?state.favorites.delete(id):state.favorites.add(id);localStorage.setItem('apex_favs',JSON.stringify([...state.favorites]));renderCards()}if(action==='detail')showDetail(id);if(action==='quick')showQuickSite(id);if(action==='models')loadModelComparison(id,btn.dataset.day,true);if(action==='edit')openEdit(id);if(action==='delete')deleteSite(id)});}
init();

// Selector de días del pronóstico ampliado
document.addEventListener('click',e=>{const b=e.target.closest?.('[data-day][data-site]');if(b)showDetail(b.dataset.site,b.dataset.day)});

// Cada apertura o restauración de página comienza en Satélite.
window.addEventListener('pageshow',()=>{if(!state.map||!state.sat)return;if(state.osm&&state.map.hasLayer(state.osm))state.map.removeLayer(state.osm);if(!state.map.hasLayer(state.sat))state.sat.addTo(state.map);state.satellite=true;const btn=document.getElementById('layerBtn');if(btn){btn.textContent='Vista: Satélite';btn.title='Estás viendo Satélite. Clic para cambiar a Calles';}});
